-- Devil n Dove Build 264 — content editability, project-first CAIP and explicit merchandising order.
-- Apply after Build 263. Idempotent and non-destructive.
PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS public_display_priorities (
  public_display_priority_id INTEGER PRIMARY KEY AUTOINCREMENT,
  surface_key TEXT NOT NULL,
  record_type TEXT NOT NULL CHECK(record_type IN ('product','creation')),
  record_id INTEGER NOT NULL,
  priority_rank INTEGER NOT NULL DEFAULT 9999,
  is_pinned INTEGER NOT NULL DEFAULT 0 CHECK(is_pinned IN (0,1)),
  notes TEXT,
  updated_by INTEGER,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(surface_key,record_type,record_id),
  FOREIGN KEY(updated_by) REFERENCES users(user_id) ON DELETE SET NULL
);

CREATE INDEX IF NOT EXISTS idx_public_display_priorities_surface ON public_display_priorities(surface_key,is_pinned DESC,priority_rank,record_type,record_id);

CREATE TABLE IF NOT EXISTS creative_project_cost_context (
  creative_work_project_id INTEGER PRIMARY KEY,
  cost_purpose TEXT NOT NULL DEFAULT 'research_experiment' CHECK(cost_purpose IN ('content_marketing','research_experiment','product_development','education_training','internal_other')),
  internal_notes TEXT,
  updated_by INTEGER,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY(creative_work_project_id) REFERENCES creative_work_projects(creative_work_project_id) ON DELETE CASCADE,
  FOREIGN KEY(updated_by) REFERENCES users(user_id) ON DELETE SET NULL
);

-- Every Creative Process project gets a CAIP workspace, even when no sellable product exists.
SELECT 'CAIP-WORK-'||w.creative_work_project_id,'creative_work_project',CAST(w.creative_work_project_id AS TEXT),
       COALESCE((SELECT l.product_id FROM creative_project_product_links l WHERE l.creative_work_project_id=w.creative_work_project_id ORDER BY l.is_primary DESC,l.creative_project_product_link_id LIMIT 1),w.product_id),
       w.project_title,'intake','needs_review','intake',
       json_object('creative_work_project_id',w.creative_work_project_id,'project_key',w.project_key,'project_type',w.project_type,'summary',COALESCE(w.summary,''),'objective',COALESCE(w.objective,''),'story_angle',COALESCE(w.story_angle,'')),
       '{}',w.created_by,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP
FROM creative_work_projects w WHERE 1=1
ON CONFLICT(source_type,source_id) DO UPDATE SET product_id=COALESCE(excluded.product_id,creative_projects.product_id),project_title=excluded.project_title,source_snapshot_json=excluded.source_snapshot_json,updated_at=CURRENT_TIMESTAMP;

SELECT w.creative_work_project_id,c.creative_project_id,NULL,0,'workspace_ready',w.updated_by,CURRENT_TIMESTAMP,'Build 264: CAIP workspace available for productless research/experiment and content projects.'
FROM creative_work_projects w JOIN creative_projects c ON c.source_type='creative_work_project' AND c.source_id=CAST(w.creative_work_project_id AS TEXT) WHERE 1=1
ON CONFLICT(creative_work_project_id,creative_project_id) DO UPDATE SET mirrored_at=CURRENT_TIMESTAMP,notes=excluded.notes;

-- Research/content projects still need material usage and cost analysis outputs.
INSERT OR IGNORE INTO creative_work_outputs(creative_work_project_id,output_key,output_label,output_group)
SELECT creative_work_project_id,'material_usage','Material usage report','operations' FROM creative_work_projects WHERE LOWER(COALESCE(project_type,'')) IN ('content_only','education','research','archive');

INSERT OR IGNORE INTO creative_work_outputs(creative_work_project_id,output_key,output_label,output_group)
SELECT creative_work_project_id,'cost_analysis','Cost analysis','operations' FROM creative_work_projects WHERE LOWER(COALESCE(project_type,'')) IN ('content_only','education','research','archive');

-- Build 264 explicit static edit locations, including Home card messages/links/colours and Shop presentation.

-- Media/content slot seed batch 1 of 4 (split for Cloudflare D1 statement-size limits).
ON CONFLICT(page_path,slot_key) DO UPDATE SET slot_label=excluded.slot_label,slot_type=excluded.slot_type,target_selector=excluded.target_selector,target_attribute=excluded.target_attribute,source_snapshot=excluded.source_snapshot,source_alt_snapshot=excluded.source_alt_snapshot,is_required=excluded.is_required,is_active=1,updated_at=CURRENT_TIMESTAMP;;

-- Media/content slot seed batch 2 of 4 (split for Cloudflare D1 statement-size limits).
ON CONFLICT(page_path,slot_key) DO UPDATE SET slot_label=excluded.slot_label,slot_type=excluded.slot_type,target_selector=excluded.target_selector,target_attribute=excluded.target_attribute,source_snapshot=excluded.source_snapshot,source_alt_snapshot=excluded.source_alt_snapshot,is_required=excluded.is_required,is_active=1,updated_at=CURRENT_TIMESTAMP;;

-- Media/content slot seed batch 3 of 4 (split for Cloudflare D1 statement-size limits).
ON CONFLICT(page_path,slot_key) DO UPDATE SET slot_label=excluded.slot_label,slot_type=excluded.slot_type,target_selector=excluded.target_selector,target_attribute=excluded.target_attribute,source_snapshot=excluded.source_snapshot,source_alt_snapshot=excluded.source_alt_snapshot,is_required=excluded.is_required,is_active=1,updated_at=CURRENT_TIMESTAMP;;

-- Media/content slot seed batch 4 of 4 (split for Cloudflare D1 statement-size limits).
ON CONFLICT(page_path,slot_key) DO UPDATE SET slot_label=excluded.slot_label,slot_type=excluded.slot_type,target_selector=excluded.target_selector,target_attribute=excluded.target_attribute,source_snapshot=excluded.source_snapshot,source_alt_snapshot=excluded.source_alt_snapshot,is_required=excluded.is_required,is_active=1,updated_at=CURRENT_TIMESTAMP;;

SELECT s.media_content_slot_id,s.page_path,s.slot_key,'text',COALESCE(s.source_snapshot,''),COALESCE(s.source_snapshot,''),0,0,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP
FROM media_content_slots s
WHERE s.is_active=1 AND s.slot_type='text'
ON CONFLICT(media_content_slot_id) DO UPDATE SET page_path=excluded.page_path,slot_key=excluded.slot_key,updated_at=CURRENT_TIMESTAMP;

VALUES('build264_content_project_merchandising','database_build264_content_project_merchandising.sql',NULL,'applied',0,CURRENT_TIMESTAMP,
'Adds explicit Home/Gallery/Creations merchandising order; makes research/content Creative Projects first-class CAIP workspaces with project inventory cost context; and seeds Build 264 Home/Shop Media Studio slots.',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)
ON CONFLICT(migration_key) DO UPDATE SET file_name=excluded.file_name,status='applied',destructive=0,applied_at=COALESCE(schema_migration_ledger.applied_at,CURRENT_TIMESTAMP),notes=excluded.notes,updated_at=CURRENT_TIMESTAMP;
